nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    return xi.mmm.onVoucherUse(target, item, action)\nend\n\nreturn itemObject\n"},["scripts/items/maze_voucher_09.lua"]={["Path"]="scripts/items/maze_voucher_09.lua",["SHA256"]="0a1f4e1a74963c5502d2c134aa0ba0c7599dfc2748aa265c956f59a5fae2c7b9",["Text"]="-----------------------------------\n-- ID: 28744\n-- Maze Voucher 09\n-- A slip of paper containing maze construction specifications.\n-- To order a maze, it must be attached to a Maze Tabula.\n-- It reads, \"Revitalization Team.\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.mmm.onVoucherCheck(target, item)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    return xi.mmm.onVoucherUse(target, item, action)\nend\n\nreturn itemObject\n"},["scripts/items/meat_chiefkabob.lua"]={["Path"]="scripts/items/meat_chiefkabob.lua",["SHA256"]="b718675311db73361a9b73be610fb5983566a18a8f76a6f8230df3b814285bb6",["Text"]="-----------------------------------\n-- ID: 4574\n-- Item: meat_chiefkabob\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Strength 5\n-- Agility 1\n-- Intelligence -2\n-- Attack % 22\n-- Attack Cap 65\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 5)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.INT, -2)\n    effect:addMod(xi.mod.FOOD_ATTP, 22)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 65)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/meat_mithkabob.lua"]={["Path"]="scripts/items/meat_mithkabob.lua",["SHA256"]="c3ed0245c29af5b8cf71be93a73708b7702a8d458b5da921a8eedcd6c0417deb",["Text"]="-----------------------------------\n-- ID: 4381\n-- Item: meat_mithkabob\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Strength 5\n-- Agility 1\n-- Intelligence -2\n-- Attack % 22\n-- Attack Cap 60\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 5)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.INT, -2)\n    effect:addMod(xi.mod.FOOD_ATTP, 22)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 60)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/meatloaf.lua"]={["Path"]="scripts/items/meatloaf.lua",["SHA256"]="e1bd0238f8e572ac5f49d9e7f9e905a4f54c10753f1abc2f3948fceec431b44d",["Text"]="-----------------------------------\n-- ID: 5689\n-- Item: Meatloaf\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- Strength 6\n-- Agility 2\n-- Intelligence -3\n-- Attack 18% Cap 90\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 6)\n    effect:addMod(xi.mod.AGI, 2)\n    effect:addMod(xi.mod.INT, -3)\n    effect:addMod(xi.mod.FOOD_ATTP, 18)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 90)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/meatloaf_+1.lua"]={["Path"]="scripts/items/meatloaf_+1.lua",["SHA256"]="3be0500d41d6cfd0aafd0722b95883ade97499093a99662814868dbdf26db65c",["Text"]="-----------------------------------\n-- ID: 5690\n-- Item: Meatloaf +1\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- Strength 6\n-- Agility 2\n-- Intelligence -3\n-- Attack 18% Cap 95\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 6)\n    effect:addMod(xi.mod.AGI, 2)\n    effect:addMod(xi.mod.INT, -3)\n    effect:addMod(xi.mod.FOOD_ATTP, 18)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 95)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/mediocris_cell.lua"]={["Path"]="scripts/items/mediocris_cell.lua",["SHA256"]="57658bc9830ff8305e3e0c77961e3d260100b433c4ae295b9f21e4ef759ae036",["Text"]="-----------------------------------\n-- Mediocris Cell\n-- ID 5382\n-- Removes CHR Down effect\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.salvage.onCellItemCheck(target, xi.effect.DEBILITATION, 0x040)\nend\n\nitemObject.onItemUse = function(target)\n    return xi.salvage.onCellItemUse(target, xi.effect.DEBILITATION, 0x040, 17)\nend\n\nreturn itemObject\n"},["scripts/items/megalixir.lua"]={["Path"]="scripts/items/megalixir.lua",["SHA256"]="6e6647a41107181dfb1872e9785b0ca15f93e5889dedbc75fa735765d24c934d",["Text"]="-----------------------------------\n-- ID: 4254\n-- Item: Megalixir\n-- Item Effect: Instantly restores 100% of HP and MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    local mHP = target:getMaxHP()\n    local cHP = target:getHP()\n    local mMP = target:getMaxMP()\n    local cMP = target:getMP()\n\n    if mHP == cHP and mMP == cMP then\n        result = 56 -- Does not let player use item if their hp and mp are full\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    target:addHP(target:getMaxHP())\n    target:addMP(target:getMaxMP())\n    target:messageBasic(xi.msg.basic.RECOVERS_HP_AND_MP)\nend\n\nreturn itemObject\n"},["scripts/items/meifu_goma.lua"]={["Path"]="scripts/items/meifu_goma.lua",["SHA256"]="f75f84b1656d44872a47bc1e4e81286df61c663df812d70fa1f366523dfa2b8c",["Text"]="-----------------------------------\n-- ID: 4185\n-- Meifu Goma\n-- A spinning firework appears on the ground and sprays sparks in a circle\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/melomane_mallet.lua"]={["Path"]="scripts/items/melomane_mallet.lua",["SHA256"]="ba4643d7b90c107cf9cf4a301385b318c740d00553b97f5418ee4b8f354606a7",["Text"]="-----------------------------------\n-- ID: 18881\n-- Melomane Mallet\n-- Enchantment: 60Min, Costume - Mandragora\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 31, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/melon_pie.lua"]={["Path"]="scripts/items/melon_pie.lua",["SHA256"]="c08aa5c32b7e7f7ec4e34e3c02a4930045e886ac6f29a6e007fa5399c26a12b1",["Text"]="-----------------------------------\n-- ID: 4421\n-- Item: melon_pie\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Magic 25\n-- Agility -1\n-- Intelligence 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 25)\n    effect:addMod(xi.mod.AGI, -1)\n    effect:addMod(xi.mod.INT, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/melon_pie_+1.lua"]={["Path"]="scripts/items/melon_pie_+1.lua",["SHA256"]="176743cd90974269b864d7bc7d183051154627625c0e64474ea28dd26e52ff39",["Text"]="-----------------------------------\n-- ID: 4523\n-- Item: melon_pie_+1\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Magic 30\n-- Intelligence 5\n-- Magic Regen While Healing 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 30)\n    effect:addMod(xi.mod.INT, 5)\n    effect:addMod(xi.mod.MPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/melon_snow_cone.lua"]={["Path"]="scripts/items/melon_snow_cone.lua",["SHA256"]="b2b870a3786ba2e9465c2b9d6a7490f433e504378bacc4f6e6808da0fb1763ef",["Text"]="-----------------------------------\n-- ID: 5712\n-- Item: Melon Snowcone\n-- Food Effect: 5 Min, All Races\n-----------------------------------\n-- HP % 10 Cap 200\n-- HP Healing 3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 10)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 200)\n    effect:addMod(xi.mod.HPHEAL, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/melt_baselard.lua"]={["Path"]="scripts/items/melt_baselard.lua",["SHA256"]="7723343dab234966228acbcce4917e724bcdfaa611dde0dca5b2da0dea976c45",["Text"]="-----------------------------------\n-- ID: 18012\n-- Item: Melt Baselard\n-- Item Effect: DEFENSE DOWN\n-- Duration:\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target)\n    -- TODO: Implement https://discord.com/channels/443544205206355968/446400612582555658/1080960539519369329\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/memento_muffler.lua"]={["Path"]="scripts/items/memento_muffler.lua",["SHA256"]="0073c9f1ac5ba5239ca27f87db90e6388471b39a980cfd2f6379f48dda53c45b",["Text"]="-----------------------------------\n-- ID: 13173\n-- Item: Memento Muffler\n-- Item Effect: VIT +7\n-- Duration: 3 minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, user)\n    if target:getStatusEffectBySource(xi.effect.VIT_BOOST, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MEMENTO_MUFFLER) ~= nil then\n        target:delStatusEffect(xi.effect.VIT_BOOST, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MEMENTO_MUFFLER)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.MEMENTO_MUFFLER) then\n        target:addStatusEffect(xi.effect.VIT_BOOST, { duration = 300, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.MEMENTO_MUFFLER })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.VIT, 7)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/mercanbaligi.lua"]={["Path"]="scripts/items/mercanbaligi.lua",["SHA256"]="19641ab9c0ae63608f4c45c2906120d0f01e806435011bd6d8fb3cdd3edf9abd",["Text"]="-----------------------------------\n-- ID: 5454\n-- Item: Mercanbaligi\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 4\n-- Mind -6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.MND, -6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/mermans_sword.lua"]={["Path"]="scripts/items/mermans_sword.lua",["SHA256"]="4b8d4ee102e91780b4d490d34d8e5fd17f206fde1124f925b4524f26d75390be",["Text"]="-----------------------------------\n-- ID: 16620\n-- Item: Merman's Sword\n-- Additional effect: water damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    local power  = utils.clamp(dStat / 2, 0, 54) -- Kinda jank looking, but it sort of aligns. Need more data.\n    local pTable =\n    {\n        chance         = 5 + utils.clamp(dStat * 0.186, 0, 10), -- 0-10% over 54 dINT, approx.\n        basePower      = math.randomInt(power + 9, power + 12),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WATER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/messhikimaru.lua"]={["Path"]="scripts/items/messhikimaru.lua",["SHA256"]="357db8729a05ad36160b5abb1e602b8a9b37d0f2b54271c9e6ef531131f6da90",["Text"]="-----------------------------------\n-- ID: 17826\n-- Item: Messhikimaru\n-- Enchantment: Arcana Killer\n-- Durration: 10 Mins\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.MESSHIKIMARU) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 600, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.MESSHIKIMARU })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.ARCANA_KILLER, 20)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/metal_slime_hat.lua"]={["Path"]="scripts/items/metal_slime_hat.lua",["SHA256"]="1dfe6817a93e9f06b3ee590a7e8ba3900c7235f248e631b869277ed37a5e41f9",["Text"]="-----------------------------------\n-- ID: 27727\n-- Item: Metal Slime Hat\n-- Dispense: Metal Slime Candy\n-- TODO: Add hidden set effect\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.METAL_SLIME_CANDY, math.randomInt(5, 12) } })\nend\n\nreturn itemObject\n"},["scripts/items/mhaura_earring.lua"]={["Path"]="scripts/items/mhaura_earring.lua",["SHA256"]="31b22ec01128752fa5e644d93822dd9a6be7f5e1e058b5b5d24bbfeee649e216",["Text"]="-----------------------------------\n-- ID: 16044\n-- Mhaura Earring\n-- Enchantment: \"Teleport\" (Mhaura)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.MHAURA_EARRING, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/midrium_bolt_quiver.lua"]={["Path"]="scripts/items/midrium_bolt_quiver.lua",["SHA256"]="6facce44517d183e21a5cb98f5cb4e2ec98fb700aa887e260f3c0db8c71194dd",["Text"]="-----------------------------------\n-- ID: 6139\n-- Item: Mid. Bolt Quiver\n-- When used, you will obtain one stack of Midrium Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.MIDRIUM_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/midwinter_dream.lua"]={["Path"]="scripts/items/midwinter_dream.lua",["SHA256"]="29454d010bfaeb6353bfb63689406d39ea53c949eb0d1ea52600363eaa06b849",["Text"]="-----------------------------------\n-- ID: 5543\n-- Item: midwinter_dream\n-- Food Effect: 4 Hrs, All Races\n-----------------------------------\n-- TODO: Group Effect\n-- HP 10\n-- MP 8% Cap 60\n-- Intelligence 2\n-- HP Recovered while healing 2\n-- MP Recovered while healing 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 10)\n    effect:addMod(xi.mod.INT, 2)\n    effect:addMod(xi.mod.FOOD_MPP, 8)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 60)\n    effect:addMod(xi.mod.HPHEAL, 2)\n    effect:addMod(xi.mod.MPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/mighty_ring.lua"]={["Path"]="scripts/items/mighty_ring.lua",["SHA256"]="3590fd08f0111f73512a556f33d1922ed5d1644d9c6dc60827f4c59f1909f087",["Text"]="-----------------------------------\n-- ID: 15558\n-- Item: mighty_ring\n-- Item Effect: Attack +5, Ranged Attack +5\n-- Duration: 30 Minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MIGHTY_RING) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MIGHTY_RING)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.MIGHTY_RING) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.MIGHTY_RING })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.ATT, 5)\n    effect:addMod(xi.mod.RATT, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/mihgo_mithkabob.lua"]={["Path"]="scripts/items/mihgo_mithkabob.lua",["SHA256"]="f36b8660b86959a2beb4d9821977d42fdfa0a9acbca164a98194f4595a87d04b",["Text"]="-----------------------------------\n-- ID: 5708\n-- Item: Mihgo Mithkabob\n-- Food Effect: 4 Hrs, All Races\n-----------------------------------\n-- Dexterity 5\n-- Vitality 2\n-- Mind -2\n-- Accuracy +50\n-- Ranged Accuracy +50\n-- Evasion +5\n-- Defense % 25 (cap 95)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 5)\n    effect:addMod(xi.mod.VIT, 2)\n    effect:addMod(xi.mod.MND, -2)\n    effect:addMod(xi.mod.ACC, 50)\n    effect:addMod(xi.mod.RACC, 50)\n    effect:addMod(xi.mod.EVA, 5)\n    effect:addMod(xi.mod.FOOD_DEFP, 25)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 95)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/mind_potion.lua"]={["Path"]="scripts/items/mind_potion.lua",["SHA256"]="d4699bf997c7b22f4fa502ebce39c03b9374a30ab019783930fb6b61c0480a7c",["Text"]="-----------------------------------\n--  ID: 4209\n--  Item: Mind Potion\n--  Mind 7\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.MND_BOOST, { power = 7, duration = 180, origin = user })\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 900, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/misers_die.lua"]={["Path"]="scripts/items/misers_die.lua",["SHA256"]="3e1bbf9657612d846c12e94a46d7df9aa66888e3df11ba0e8a76cbe78817e196",["Text"]="-----------------------------------\n-- ID: 5503\n-- Miser's Die\n-- Teaches the job ability Miser's Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.MISERS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.MISERS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/mist_crown.lua"]={["Path"]="scripts/items/mist_crown.lua",["SHA256"]="58b651721d305c063e53f642f82ddc1fc7dc49e3e10f32179006229d7b5ce8ee",["Text"]="-----------------------------------\n-- ID: 15162\n-- Item: Mist Crown\n-- Item Effect: Evasion Boost\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.EVASION_BOOST, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MIST_CROWN) ~= nil then\n        target:delStatusEffect(xi.effect.EVASION_BOOST, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MIST_CROWN)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.MIST_CROWN) then\n        if not target:hasStatusEffect(xi.effect.EVASION_BOOST) then\n            target:addStatusEffect(xi.effect.EVASION_BOOST, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.MIST_CROWN })\n        else\n            target:messageBasic(xi.msg.basic.NO_EFFECT)\n        end\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.EVA, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/mist_mitts.lua"]={["Path"]="scripts/items/mist_mitts.lua",["SHA256"]="e7f44b706fb8113aa051a2d327347d668e177ff5d5d61281b4e0ce3b859b64c5",["Text"]="-----------------------------------\n-- ID: 14855\n-- Item: Mist Mitts\n-- Item Effect: Evasion Boost\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.EVASION_BOOST, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MIST_MITTS) ~= nil then\n        target:delStatusEffect(xi.effect.EVASION_BOOST, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MIST_MITTS)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.MIST_MITTS) then\n        if not target:hasStatusEffect(xi.effect.EVASION_BOOST) then\n            target:addStatusEffect(xi.effect.EVASION_BOOST, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.MIST_MITTS })\n        else\n            target:messageBasic(xi.msg.basic.NO_EFFECT)\n        end\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.EVA, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/mist_pumps.lua"]={["Path"]="scripts/items/mist_pumps.lua",["SHA256"]="53ab024e1237ddb35fa35c3ee40218dc8a94a18d6daf6b3251128bce3d805289",["Text"]="-----------------------------------\n-- ID: 15312\n-- Item: Mist Pumps\n-- Item Effect: Evasion Boost\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.EVASION_BOOST, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MIST_PUMPS) ~= nil then\n        target:delStatusEffect(xi.effect.EVASION_BOOST, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MIST_PUMPS)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.MIST_PUMPS) then\n        if not target:hasStatusEffect(xi.effect.EVASION_BOOST) then\n            target:addStatusEffect(xi.effect.EVASION_BOOST, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.MIST_PUMPS })\n        else\n            target:messageBasic(xi.msg.basic.NO_EFFECT)\n        end\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.EVA, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/mist_slacks.lua"]={["Path"]="scripts/items/mist_slacks.lua",["SHA256"]="d7ceb6db0766d2ad68d34752252d8ad5a67e8017f533b8ecf50ed770cc105845",["Text"]="-----------------------------------\n-- ID: 14324\n-- Item: Mist Slacks\n-- Item Effect: Evasion Boost\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.EVASION_BOOST, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MIST_SLACKS) ~= nil then\n        target:delStatusEffect(xi.effect.EVASION_BOOST, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MIST_SLACKS)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.MIST_SLACKS) then\n        if not target:hasStatusEffect(xi.effect.EVASION_BOOST) then\n            target:addStatusEffect(xi.effect.EVASION_BOOST, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.MIST_SLACKS })\n        else\n            target:messageBasic(xi.msg.basic.NO_EFFECT)\n        end\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.EVA, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/mist_tunic.lua"]={["Path"]="scripts/items/mist_tunic.lua",["SHA256"]="5a34ae4e58e665a164cfc53daa6f0dbdf5b88cfcc468c823e0873d40c774d922",["Text"]="-----------------------------------\n-- ID: 14423\n-- Item: Mist Tunic\n-- Item Effect: Evasion Boost\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.EVASION_BOOST, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MIST_TUNIC) ~= nil then\n        target:delStatusEffect(xi.effect.EVASION_BOOST, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MIST_TUNIC)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.MIST_TUNIC) then\n        if not target:hasStatusEffect(xi.effect.EVASION_BOOST) then\n            target:addStatusEffect(xi.effect.EVASION_BOOST, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.MIST_TUNIC })\n        else\n            target:messageBasic(xi.msg.basic.NO_EFFECT)\n        end\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.EVA, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"}};
